-- ---------------------------------------------------------------------------
-- Demo bookings and payments. Only for preview tenants, always marked is_demo,
-- never more than one per (tenant, resource, moment).
-- ---------------------------------------------------------------------------
do $$
declare
  v_tenant uuid;
  v_service record;
  v_resource uuid;
  v_customer uuid;
  v_booking uuid;
  v_starts timestamptz;
  v_window tstzrange;
  v_day date;
  v_attempt integer := 0;
begin
  select id into v_tenant from public.tenants where slug = 'akzhol-motors';
  if v_tenant is null then return; end if;
  -- demo rows are only ever written into a preview tenant
  if (select status from public.tenants where id = v_tenant) <> 'preview' then return; end if;
  if exists (select 1 from public.bookings where tenant_id = v_tenant and is_demo) then return; end if;

  select s.id, s.duration_min, s.buffer_before_min, s.buffer_after_min, s.price_cents, s.currency
    into v_service
  from public.services s
  where s.tenant_id = v_tenant and s.key = 'diagnostics' and s.is_active
  limit 1;
  if v_service.id is null then return; end if;

  select r.id into v_resource
  from public.resources r
  where r.tenant_id = v_tenant and r.is_active
  order by r.sort_order, r.key limit 1;
  if v_resource is null then return; end if;

  insert into public.customers (tenant_id, name, phone, phone_normalized, is_demo)
  values (v_tenant, 'Демо-клиент', '+7 000 000-00-00', '70000000000', true)
  on conflict (tenant_id, phone_normalized) do update set is_demo = true
  returning id into v_customer;

  -- find the first free slot in the next three weeks, walking the working windows
  for v_day in select g::date from generate_series(
      (now() at time zone app.tenant_timezone(v_tenant))::date + 1,
      (now() at time zone app.tenant_timezone(v_tenant))::date + 21,
      interval '1 day') as g
  loop
    exit when v_booking is not null;
    for v_window in select * from app.working_windows(v_tenant, v_day) loop
      exit when v_booking is not null;
      v_starts := lower(v_window);
      v_attempt := 0;
      while v_starts < upper(v_window) and v_booking is null and v_attempt < 40 loop
        v_attempt := v_attempt + 1;
        begin
          insert into public.bookings (
            tenant_id, customer_id, service_id, resource_id, display_number,
            price_cents, currency, duration_min, buffer_before_min, buffer_after_min,
            service_name_snapshot, starts_at, ends_at, status, access_token_hash,
            idempotency_hash, is_demo
          )
          select
            v_tenant, v_customer, v_service.id, v_resource,
            app.next_counter(v_tenant, 'booking'),
            v_service.price_cents, v_service.currency, v_service.duration_min,
            v_service.buffer_before_min, v_service.buffer_after_min,
            (select s.name from public.services s where s.id = v_service.id),
            v_starts, v_starts + make_interval(mins => v_service.duration_min),
            'confirmed', digest('demo-seed-token:' || v_tenant::text || ':' || v_starts::text, 'sha256'),
            digest('demo-seed:' || v_starts::text, 'sha256'), true
          returning id into v_booking;

          insert into public.resource_occupancies (tenant_id, resource_id, booking_id, kind, period)
          select v_tenant, v_resource, v_booking, 'booking', b.occupancy
          from public.bookings b where b.id = v_booking;
        exception
          when exclusion_violation or unique_violation then
            v_booking := null;
        end;
        v_starts := v_starts + make_interval(mins => 30);
      end loop;
    end loop;
  end loop;

  if v_booking is not null then
    insert into public.booking_events (tenant_id, booking_id, event, actor, payload)
    values (v_tenant, v_booking, 'booking_created', 'system', '{"demo":true}'::jsonb);

    insert into public.payments (tenant_id, booking_id, amount_cents, currency, method, status, paid_at, is_demo)
    select v_tenant, v_booking, v_service.price_cents, v_service.currency, 'cash', 'paid', now(), true;
  end if;
end;
$$;

